def update(self, object_states: dict[str, Any], *, sim_step: int) -> StageResult:
        condition_true: dict[str, bool] = {}
        for stage, stage_id in zip(self._stages, self._stage_ids):
            condition = stage.get("success_condition")
            if not isinstance(condition, dict):
                condition_true[stage_id] = False
                continue
            ctx = self._ctx[stage_id]
            condition_true[stage_id] = evaluate_condition_node(condition, object_states, ctx)

        # ``current`` means that a stage's own predicate is true now, after its
        # dependencies have been reached at some point.  Requiring every
        # dependency predicate to remain true in the same frame makes current
        # progress meaningless for normal sequential tasks (for example an
        # open-door stage must become false again when the final close-door
        # stage succeeds).
        current_completed = self._resolve_current(
            condition_true,
            previously_completed=self._completed,
        )
        latched_completed = {
            stage_id: bool(self._completed[stage_id] or current_completed[stage_id])
            for stage_id in self._stage_ids
        }
        for stage_id, completed in latched_completed.items():
            if completed and not self._completed[stage_id]:
                self._completed[stage_id] = True
                self._first_step[stage_id] = int(sim_step)
        self._current_completed = current_completed
        return self._result()

def check_success(states: StateMap, ctx: Dict[str, Any], params: Dict[str, Any]) -> bool:
    phase = str((params or {}).get("phase", "terminal"))
    pot = "obj_330_pot_1"
    bowl = "obj_330_bowl_2"
    if not _has(states, "obj_333_stove_1", pot, bowl, "obj_330_ladle_3"):
        return False

    # Named phases for YAML stages
    if phase == "ladle_returned":
        return _head_in_pot_zone(states)
    if phase == "bowl_placed":
        return _bowl_in_serve_zone(states)
    if phase == "bowl_upright":
        return _bowl_upright_76(states)

    # State machine (scoop1 / scoop2 / terminal)
    scoop1_done = bool(ctx.get("scoop1_done", False))
    scoop2_done = bool(ctx.get("scoop2_done", False))
    was_in_pot = bool(ctx.get("was_in_pot", _head_in_pot_zone(states)))

    if not scoop1_done:
        if was_in_pot and _head_above_bowl(states):
            scoop1_done = True
            was_in_pot = False
        elif _head_in_pot_zone(states):
            was_in_pot = True

    elif not scoop2_done:
        if was_in_pot and _head_above_bowl(states):
            scoop2_done = True
            was_in_pot = False
        elif _head_in_pot_zone(states):
            was_in_pot = True

    ctx["scoop1_done"] = scoop1_done
    ctx["scoop2_done"] = scoop2_done
    ctx["was_in_pot"] = was_in_pot

    if phase == "scoop1":
        return scoop1_done
    if phase == "scoop2":
        return scoop2_done

    # Terminal: both scoops done, ladle returned, bowl placed, bowl upright
    return (scoop1_done and scoop2_done
            and _head_in_pot_zone(states)
            and _bowl_in_serve_zone(states)
            and _bowl_upright_76(states))

def check_success(
    states: Dict[str, Any],
    ctx: Dict[str, Any],
    params: Dict[str, Any],
) -> bool:
    mode = str((params or {}).get("mode", "terminal"))
    strikes = _update_hammer_strikes(states, ctx)

    if mode == "hammer_strike":
        return strikes >= REQUIRED_STRIKES
    if mode == "hammer_placed":
        return _hammer_placed(states)

    # Terminal: both screwdrivers in box + hammer in box + hammer struck wood once
    return _tools_placed(states) and _hammer_placed(states) and strikes >= REQUIRED_STRIKES

def check_success(
    states: Dict[str, Any],
    ctx: Dict[str, Any],
    params: Dict[str, Any],
) -> bool:
    """Evaluate success.

    Parameters
    ----------
    states:
        Object-id → state-dict mapping (must contain *pose_world*).
    ctx:
        Mutable context dict shared across calls for the same evaluation scope.
        Used to track sequence progress and latch pour detection.
    params:
        YAML-specified ``params`` dict.  ``mode`` can be ``"pour_only"``
        (used by the *pour_wine* stage), ``"returned"`` (used by the
        *return_bottle* stage), or omitted for the full terminal check.
    """
    mode = params.get("mode", "full")

    # -- pour_only: used by the pour_wine stage ---------------------------
    if mode == "pour_only":
        if not ctx.get("_pour_detected", False):
            if _check_pour(states):
                ctx["_pour_detected"] = True
        return bool(ctx.get("_pour_detected", False))

    # -- returned: used by the return_bottle stage ------------------------
    if mode == "returned":
        return _check_bottle_in_fridge(states) and _check_bottle_upright(states)

    # -- full: sequence --------------------------------------------
    step = int(ctx.get("_step", 0))

    if step == 0 and _check_fridge_open(states):
        ctx["_step"] = 1

    if step == 1 and _check_bottle_lifted(states):
        ctx["_step"] = 2

    if step == 2:
        if _check_pour(states):
            ctx["_step"] = 3

    if step == 3 and _check_bottle_in_fridge(states) and _check_bottle_upright(states):
        ctx["_step"] = 4

    if step == 4 and _check_fridge_closed(states):
        ctx["_step"] = 5

    return int(ctx.get("_step", 0)) >= 5

def check_success(
    states: Dict[str, Any],
    ctx: Dict[str, Any],
    params: Dict[str, Any],
) -> bool:
    phase = str(params.get("phase", "terminal"))

    # --- Phase-specific returns ------------------------------------------
    if phase == "spoon_in_mug":
        return _spoon_in_mug(states)
    if phase == "mug_under_faucet":
        return _mug_under_faucet(states)
    if phase == "faucet_open_close":
        return _faucet_cycle_done(states, ctx)
    if phase == "mug_on_tray":
        return _mug_on_tray(states)

    # --- Terminal: ordered sequence with latching ------------------------
    if not _has(states, SPOON, MUG, FAUCET, TRAY):
        return False

    spoon_ok = _spoon_in_mug(states)
    mug_faucet_ok = _mug_under_faucet(states)
    faucet_ok = _faucet_cycle_done(states, ctx)
    mug_tray_ok = _mug_on_tray(states)

    # Strict sequence: spoon in mug → mug under faucet → faucet cycle →
    # mug on tray.  Final frame also requires spoon still in mug.
    step = int(ctx.get("step", 0))
    if step == 0 and spoon_ok:
        step = 1
    if step == 1 and mug_faucet_ok:
        step = 2
    if step == 2 and faucet_ok:
        step = 3
    if step == 3 and mug_tray_ok and spoon_ok:
        step = 4
    ctx["step"] = step
    return step >= 4

def check_success(states: StateMap, ctx: Dict[str, Any], params: Dict[str, Any]) -> bool:
    phase = str((params or {}).get("phase", "terminal"))
    keyboard = "obj_098_keyboard_2"
    mouse = "obj_300_mouse_3"
    if not _has(states, "obj_090_display_1", keyboard, mouse):
        return False
    if phase == "monitor_straight":
        return _monitor_straight(states)
    if phase == "esc_pressed":
        return _keyboard_esc_pressed(states, ctx)
    if phase == "mouse_clicked":
        return _mouse_left_clicked(states, ctx)
    step = int(ctx.get("step", 0))
    if step == 0 and _monitor_straight(states):
        step = 1
    if step == 1 and _keyboard_esc_pressed(states, ctx):
        step = 2
    if step == 2 and _mouse_left_clicked(states, ctx):
        step = 3
    ctx["step"] = step
    return step >= 3

def check_success(states: StateMap, ctx: Dict[str, Any], params: Dict[str, Any]) -> bool:
    phase = str((params or {}).get("phase", "terminal"))
    if phase == "assembled":
        return _puzzle_assembled(states)
    if phase == "separated":
        return _puzzle_separated(states)
    if phase in _PUZZLE_TARGETS:
        return _puzzle_piece_placed(states, phase)
    # Terminal: pieces assembled into rectangle around fixed piece_1
    return _puzzle_assembled(states)

def check_success(states: Dict[str, Any], ctx: Dict[str, Any], params: Dict[str, Any]) -> bool:
    phase = str(params.get("phase", "terminal"))

    if phase == "one_placed":
        return _count_placed(states) >= 1
    if phase == "two_placed":
        return _count_placed(states) >= 2
    if phase == "three_placed":
        return _count_placed(states) >= 3

    # terminal: all 3 placed and upright AND at rest
    return (
        _count_placed(states) >= 3
        and all(_upright(states, g) for g in GLASS_IDS)
        and _glasses_static(states)
    )

